import 'dart:convert';
import 'dart:typed_data';

/// Decoder for the native 中育云笔记 page snapshot format.
///
/// This is the protobuf message generated by `com.zykj.board.EzyPageSnapshot`
/// in the Android client. It intentionally has no dependency on the older
/// ZIP/blackboard format used elsewhere in the application.
class CloudNoteSnapshot {
  const CloudNoteSnapshot({this.cameraMatrix, this.graphSnapshot});

  final CloudNoteMatrix? cameraMatrix;
  final CloudNoteGraph? graphSnapshot;

  factory CloudNoteSnapshot.parse(Uint8List bytes) {
    final reader = _ProtoReader(bytes);
    CloudNoteMatrix? cameraMatrix;
    CloudNoteGraph? graphSnapshot;
    while (!reader.done) {
      final field = reader.readTag();
      switch (field.number) {
        case 1:
          _expectWire(field, 2);
          cameraMatrix = CloudNoteMatrix.parse(reader.readBytes());
        case 2:
          _expectWire(field, 2);
          graphSnapshot = CloudNoteGraph.parse(reader.readBytes());
        default:
          reader.skip(field.wireType);
      }
    }
    return CloudNoteSnapshot(
      cameraMatrix: cameraMatrix,
      graphSnapshot: graphSnapshot,
    );
  }
}

class CloudNoteGraph {
  CloudNoteGraph({
    Uint8List? idBytes,
    this.graphEnum = 0,
    this.outRect,
    this.matrix,
    this.childGraph = const <CloudNoteGraph>[],
    Uint8List? sourceFileNameBytes,
    this.sourceId = 0,
    this.backgroundColor = 0,
    this.paint,
    Uint8List? contentBytes,
    this.pointList = const <CloudNotePoint>[],
    Uint8List? filePathBytes,
  }) : idBytes = idBytes ?? _emptyBytes,
       sourceFileNameBytes = sourceFileNameBytes ?? _emptyBytes,
       contentBytes = contentBytes ?? _emptyBytes,
       filePathBytes = filePathBytes ?? _emptyBytes;

  /// Raw protobuf bytes for string fields. They are kept because old pages
  /// can contain malformed/non-UTF8 payloads.
  final Uint8List idBytes;
  final int graphEnum;
  final CloudNoteRect? outRect;
  final CloudNoteMatrix? matrix;
  final List<CloudNoteGraph> childGraph;
  final Uint8List sourceFileNameBytes;
  final int sourceId;
  final int backgroundColor;
  final CloudNotePaint? paint;
  final Uint8List contentBytes;
  final List<CloudNotePoint> pointList;
  final Uint8List filePathBytes;

  String? get id => _decodeUtf8(idBytes);
  String? get sourceFileName => _decodeUtf8(sourceFileNameBytes);
  String? get content => _decodeUtf8(contentBytes);
  String? get filePath => _decodeUtf8(filePathBytes);
  int get backgroundColorArgb => backgroundColor & 0xffffffff;

  factory CloudNoteGraph.parse(Uint8List bytes) {
    final reader = _ProtoReader(bytes);
    var idBytes = Uint8List(0);
    var graphEnum = 0;
    CloudNoteRect? outRect;
    CloudNoteMatrix? matrix;
    final childGraph = <CloudNoteGraph>[];
    var sourceFileNameBytes = Uint8List(0);
    var sourceId = 0;
    var backgroundColor = 0;
    CloudNotePaint? paint;
    var contentBytes = Uint8List(0);
    final pointList = <CloudNotePoint>[];
    var filePathBytes = Uint8List(0);
    while (!reader.done) {
      final field = reader.readTag();
      switch (field.number) {
        case 1:
          _expectWire(field, 2);
          idBytes = reader.readBytes();
        case 2:
          _expectWire(field, 0);
          graphEnum = reader.readInt32();
        case 3:
          _expectWire(field, 2);
          outRect = CloudNoteRect.parse(reader.readBytes());
        case 4:
          _expectWire(field, 2);
          matrix = CloudNoteMatrix.parse(reader.readBytes());
        case 5:
          _expectWire(field, 2);
          childGraph.add(CloudNoteGraph.parse(reader.readBytes()));
        case 6:
          _expectWire(field, 2);
          sourceFileNameBytes = reader.readBytes();
        case 7:
          _expectWire(field, 0);
          sourceId = reader.readInt32();
        case 8:
          _expectWire(field, 0);
          backgroundColor = reader.readInt32();
        case 9:
          _expectWire(field, 2);
          paint = CloudNotePaint.parse(reader.readBytes());
        case 10:
          _expectWire(field, 2);
          contentBytes = reader.readBytes();
        case 11:
          _expectWire(field, 2);
          pointList.add(CloudNotePoint.parse(reader.readBytes()));
        case 12:
          _expectWire(field, 2);
          filePathBytes = reader.readBytes();
        default:
          reader.skip(field.wireType);
      }
    }
    return CloudNoteGraph(
      idBytes: idBytes,
      graphEnum: graphEnum,
      outRect: outRect,
      matrix: matrix,
      childGraph: List.unmodifiable(childGraph),
      sourceFileNameBytes: sourceFileNameBytes,
      sourceId: sourceId,
      backgroundColor: backgroundColor,
      paint: paint,
      contentBytes: contentBytes,
      pointList: List.unmodifiable(pointList),
      filePathBytes: filePathBytes,
    );
  }
}

final Uint8List _emptyBytes = Uint8List(0);

class CloudNoteRect {
  const CloudNoteRect({
    this.left = 0,
    this.top = 0,
    this.right = 0,
    this.bottom = 0,
  });

  final double left;
  final double top;
  final double right;
  final double bottom;

  factory CloudNoteRect.parse(Uint8List bytes) {
    final reader = _ProtoReader(bytes);
    var left = 0.0;
    var top = 0.0;
    var right = 0.0;
    var bottom = 0.0;
    while (!reader.done) {
      final field = reader.readTag();
      switch (field.number) {
        case 1:
          _expectWire(field, 5);
          left = reader.readFloat();
        case 2:
          _expectWire(field, 5);
          top = reader.readFloat();
        case 3:
          _expectWire(field, 5);
          right = reader.readFloat();
        case 4:
          _expectWire(field, 5);
          bottom = reader.readFloat();
        default:
          reader.skip(field.wireType);
      }
    }
    return CloudNoteRect(left: left, top: top, right: right, bottom: bottom);
  }
}

class CloudNotePoint {
  const CloudNotePoint({this.x = 0, this.y = 0});

  final double x;
  final double y;

  factory CloudNotePoint.parse(Uint8List bytes) {
    final reader = _ProtoReader(bytes);
    var x = 0.0;
    var y = 0.0;
    while (!reader.done) {
      final field = reader.readTag();
      switch (field.number) {
        case 1:
          _expectWire(field, 5);
          x = reader.readFloat();
        case 2:
          _expectWire(field, 5);
          y = reader.readFloat();
        default:
          reader.skip(field.wireType);
      }
    }
    return CloudNotePoint(x: x, y: y);
  }
}

class CloudNoteMatrix {
  const CloudNoteMatrix({
    this.eventTime = 0,
    this.scaleX = 0,
    this.skewX = 0,
    this.transX = 0,
    this.skewY = 0,
    this.scaleY = 0,
    this.transY = 0,
    this.perSp0 = 0,
    this.perSp1 = 0,
    this.perSp2 = 0,
  });

  final int eventTime;
  final double scaleX;
  final double skewX;
  final double transX;
  final double skewY;
  final double scaleY;
  final double transY;
  final double perSp0;
  final double perSp1;
  final double perSp2;

  /// Android Matrix values in column-major order, suitable for
  /// `Matrix4.fromList`.
  List<double> get values => <double>[
    scaleX,
    skewY,
    0,
    perSp0,
    skewX,
    scaleY,
    0,
    perSp1,
    0,
    0,
    1,
    0,
    transX,
    transY,
    0,
    perSp2,
  ];

  factory CloudNoteMatrix.parse(Uint8List bytes) {
    final reader = _ProtoReader(bytes);
    var eventTime = 0;
    var scaleX = 0.0;
    var skewX = 0.0;
    var transX = 0.0;
    var skewY = 0.0;
    var scaleY = 0.0;
    var transY = 0.0;
    var perSp0 = 0.0;
    var perSp1 = 0.0;
    var perSp2 = 0.0;
    while (!reader.done) {
      final field = reader.readTag();
      switch (field.number) {
        case 1:
          _expectWire(field, 0);
          eventTime = reader.readInt64();
        case 2:
          _expectWire(field, 5);
          scaleX = reader.readFloat();
        case 3:
          _expectWire(field, 5);
          skewX = reader.readFloat();
        case 4:
          _expectWire(field, 5);
          transX = reader.readFloat();
        case 5:
          _expectWire(field, 5);
          skewY = reader.readFloat();
        case 6:
          _expectWire(field, 5);
          scaleY = reader.readFloat();
        case 7:
          _expectWire(field, 5);
          transY = reader.readFloat();
        case 8:
          _expectWire(field, 5);
          perSp0 = reader.readFloat();
        case 9:
          _expectWire(field, 5);
          perSp1 = reader.readFloat();
        case 10:
          _expectWire(field, 5);
          perSp2 = reader.readFloat();
        default:
          reader.skip(field.wireType);
      }
    }
    return CloudNoteMatrix(
      eventTime: eventTime,
      scaleX: scaleX,
      skewX: skewX,
      transX: transX,
      skewY: skewY,
      scaleY: scaleY,
      transY: transY,
      perSp0: perSp0,
      perSp1: perSp1,
      perSp2: perSp2,
    );
  }
}

class CloudNotePaint {
  const CloudNotePaint({
    this.width = 0,
    this.color = 0,
    this.spacing = 0,
    this.itemLength = 0,
    this.style = 0,
    this.textSize = 0,
  });

  final double width;
  final int color;
  final double spacing;
  final double itemLength;
  final int style;
  final double textSize;

  int get colorArgb => color & 0xffffffff;

  factory CloudNotePaint.parse(Uint8List bytes) {
    final reader = _ProtoReader(bytes);
    var width = 0.0;
    var color = 0;
    var spacing = 0.0;
    var itemLength = 0.0;
    var style = 0;
    var textSize = 0.0;
    while (!reader.done) {
      final field = reader.readTag();
      switch (field.number) {
        case 1:
          _expectWire(field, 5);
          width = reader.readFloat();
        case 2:
          _expectWire(field, 0);
          color = reader.readInt32();
        case 3:
          _expectWire(field, 5);
          spacing = reader.readFloat();
        case 4:
          _expectWire(field, 5);
          itemLength = reader.readFloat();
        case 5:
          _expectWire(field, 0);
          style = reader.readInt32();
        case 6:
          _expectWire(field, 5);
          textSize = reader.readFloat();
        default:
          reader.skip(field.wireType);
      }
    }
    return CloudNotePaint(
      width: width,
      color: color,
      spacing: spacing,
      itemLength: itemLength,
      style: style,
      textSize: textSize,
    );
  }
}

String? _decodeUtf8(Uint8List bytes) {
  if (bytes.isEmpty) return '';
  try {
    return const Utf8Decoder(allowMalformed: false).convert(bytes);
  } on FormatException {
    return null;
  }
}

void _expectWire(_ProtoTag tag, int expected) {
  if (tag.wireType != expected) {
    throw FormatException(
      'Unexpected protobuf wire type ${tag.wireType} for field ${tag.number}',
    );
  }
}

class _ProtoTag {
  const _ProtoTag(this.number, this.wireType);

  final int number;
  final int wireType;
}

class _ProtoReader {
  _ProtoReader(Uint8List bytes) : _bytes = bytes;

  final Uint8List _bytes;
  var _offset = 0;

  bool get done => _offset >= _bytes.length;

  _ProtoTag readTag() {
    final raw = _readVarint();
    if (raw == 0) throw const FormatException('Invalid protobuf tag 0');
    return _ProtoTag(raw >>> 3, raw & 7);
  }

  Uint8List readBytes() {
    final length = _readVarint();
    if (length < 0 || length > _bytes.length - _offset) {
      throw const FormatException('Truncated protobuf length-delimited field');
    }
    final end = _offset + length;
    final result = Uint8List.sublistView(_bytes, _offset, end);
    _offset = end;
    return result;
  }

  int readInt32() => _readVarint().toSigned(32);

  int readInt64() => _readVarint().toSigned(64);

  double readFloat() {
    if (_bytes.length - _offset < 4) {
      throw const FormatException('Truncated protobuf fixed32 field');
    }
    final value = _bytes.buffer
        .asByteData(_bytes.offsetInBytes + _offset, 4)
        .getFloat32(0, Endian.little);
    _offset += 4;
    return value;
  }

  void skip(int wireType) {
    switch (wireType) {
      case 0:
        _readVarint();
      case 1:
        _ensureRemaining(8);
        _offset += 8;
      case 2:
        final length = _readVarint();
        _ensureRemaining(length);
        _offset += length;
      case 3:
        // Groups are deprecated but valid protobuf wire values. Skip nested
        // fields until the matching end-group tag.
        while (!done) {
          final tag = readTag();
          if (tag.wireType == 4) return;
          skip(tag.wireType);
        }
        throw const FormatException('Unterminated protobuf group');
      case 4:
        return;
      case 5:
        _ensureRemaining(4);
        _offset += 4;
      default:
        throw FormatException('Unsupported protobuf wire type $wireType');
    }
  }

  int _readVarint() {
    var result = 0;
    var shift = 0;
    while (shift < 64) {
      if (done) throw const FormatException('Truncated protobuf varint');
      final byte = _bytes[_offset++];
      if (shift == 63 && byte > 1) {
        throw const FormatException('Malformed protobuf varint');
      }
      result |= (byte & 0x7f) << shift;
      if ((byte & 0x80) == 0) return result;
      shift += 7;
    }
    throw const FormatException('Malformed protobuf varint');
  }

  void _ensureRemaining(int count) {
    if (count < 0 || count > _bytes.length - _offset) {
      throw const FormatException('Truncated protobuf field');
    }
  }
}
